import{d as c,C as t,o as u,c as p,j as a,a as o,E as r,a3 as b}from"./chunks/framework.Q4yG9rk_.js";const _=JSON.parse('{"title":"道德经第七章","description":"从天地不自生，理解后其身、外其身与无私而成其私。","frontmatter":{"title":"道德经第七章","description":"从天地不自生，理解后其身、外其身与无私而成其私。","category":"guide","aliases":["道德经第七章","老子第七章","dao de jing chapter 7"],"source":["王弼《道德真经注》卷一"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-07.md","filePath":"daoism/dao-de-jing/chapter-07.md","lastUpdated":1794189804000}'),m={name:"daoism/dao-de-jing/chapter-07.md"},k=c({...m,setup(f){const i=[{id:"endurance-without-self-seeking",label:"天长地久",showLabel:!0,sentences:[["天长地久。"],["天地所以能长且久者，以其不",{text:"自生",glossary:"zisheng"},"，故能长生。"]],note:["【白话】天长地久。天地之所以能长久，是因为它们不专为自身求生存，所以能够长存。","【王弼注择要】「自生则与物争，不自生则物归也。」王弼把不自生与不和万物争相联系，所说明的是不以自我为中心的长久。","【读法】自生在这里不作自行产生解。这是以天地说明处事的义理，不是对天地寿命或生物寿命作经验测定。"]},{id:"placing-oneself-behind",label:"后其身而身先",showLabel:!0,sentences:[["是以圣人",{text:"后",glossary:"hou"},"其身而身先，"],[{text:"外",glossary:"wai"},"其身而身存。"]],note:["【白话】所以，圣人把自己放在后面，自身反而居先；把自身的利害放到一边，自身反而得到保全。","【读法】后与外在这里都是动作：不急于争先，不让一己利害支配所有判断。后面的身先、身存是本章描述的结果，不是保证任何退让都会获得优先与安全。"]},{id:"self-fulfilment-without-possessiveness",label:"非以其无私邪",showLabel:!0,sentences:[["非以其",{text:"无私",glossary:"wusi"},"邪？故能成其私。"]],note:["【白话】不正是因为他不专为自己打算吗？所以反而能够成全自身。","【王弼注择要】「无私者，无为于身也。身先身存，故曰能成其私也。」注把成其私落实到前文的身先、身存，而非再增加一份可供攫取的利益。","【读法】这句话留下了无私与自身成全之间的张力。若先计算怎样借无私赢得更多，就重新落入自生与物争的逻辑；也不能反过来要求别人不断牺牲。"]}],n=[{id:"zisheng",term:"自生",sense:1},{id:"hou",term:"后",sense:1},{id:"wai",term:"外",sense:1},{id:"wusi",term:"无私",sense:1}];return(g,e)=>{const s=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return u(),p("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第七章",tabindex:"-1"},[o("道德经第七章 "),a("a",{class:"header-anchor",href:"#道德经第七章","aria-label":'Permalink to "道德经第七章"'},"​")],-1)),r(s,{title:"不把自己放在一切之前",summary:"本章由天地的长久，转到圣人如何安放自身。看似矛盾的后而先、外而存，最后收在无私与成其私的关系上：怎样承认自身，同时不让一己之私成为所有行动的中心？",points:[{label:"先读",text:"不自生为何与不争相连？"},{label:"再辨",text:"后、外是怎样对待自身的动作？"},{label:"后想",text:"无私还能被当作求私的手段吗？"}],hint:"竹简模式先通读；经典阅读可展开段释义、点击标记字词查义。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段级释义",tabindex:"-1"},[o("【原典层】原文与段级释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段级释义","aria-label":'Permalink to "【原典层】原文与段级释义"'},"​")],-1)),r(l,{sections:i,glossary:n,tone:"ink",density:"comfortable","aria-label":"《道德经》第七章原文"}),e[2]||(e[2]=a("h2",{id:"【导读层】核心句引读",tabindex:"-1"},[o("【导读层】核心句引读 "),a("a",{class:"header-anchor",href:"#【导读层】核心句引读","aria-label":'Permalink to "【导读层】核心句引读"'},"​")],-1)),r(d,{lines:[{text:"以其不自生，故能长生。",tone:"立意",guide:"王弼以是否与物争解释自生与不自生。先理解这一关系，再看天地如何成为圣人处事的参照。"},{text:"后其身而身先，外其身而身存。",tone:"转人",guide:"两组句子都先说如何安放自身，再说由此得到的成全。不能只留下后半句，把不争改写成保证胜出的策略。"},{text:"非以其无私邪？故能成其私。",tone:"反问",guide:"成其私并没有抹掉自身的存在，却把成全自身与不以自身为唯一目的连在一起。这份张力值得保留。"}]}),e[3]||(e[3]=a("h2",{id:"【注释层】字词释义",tabindex:"-1"},[o("【注释层】字词释义 "),a("a",{class:"header-anchor",href:"#【注释层】字词释义","aria-label":'Permalink to "【注释层】字词释义"'},"​")],-1)),r(h,{items:n}),e[4]||(e[4]=b('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-天地与圣人之间怎样承接" tabindex="-1">象：天地与圣人之间怎样承接？ <a class="header-anchor" href="#象-天地与圣人之间怎样承接" aria-label="Permalink to &quot;象：天地与圣人之间怎样承接？&quot;">​</a></h3><p>前段从天地的长久说起，后段以「是以」转到圣人，建立效法天地的关系。王弼用不与物争、万物归附解释前段，使天地之喻与人的处事连通。它是一种义理上的类比，不能把天地与人当成完全相同的主体。</p><h3 id="理-「无私而成其私」是否自相矛盾" tabindex="-1">理：「无私而成其私」是否自相矛盾？ <a class="header-anchor" href="#理-「无私而成其私」是否自相矛盾" aria-label="Permalink to &quot;理：「无私而成其私」是否自相矛盾？&quot;">​</a></h3><p>若把无私理解为自身完全消失，成其私便难以解释；若把它只当作得利的计谋，又失去无私。王弼将结果限定在身先、身存，提示可以不执著一己而仍得到自身的成全。结果与动机不同：自身获益，并不必然说明行动最初只为牟利。</p><h3 id="用-后其身是否意味着总该让位" tabindex="-1">用：后其身是否意味着总该让位？ <a class="header-anchor" href="#用-后其身是否意味着总该让位" aria-label="Permalink to &quot;用：后其身是否意味着总该让位？&quot;">​</a></h3><p>先让事情与共同需要得到适当安排，不等于自己没有表达、承担或拒绝的权利。合作中可以少争虚名，也必须清楚分配责任与资源。面对侵害或不合理要求，保护自身并不自动等于本章批评的与物争。</p><h2 id="【解读层】现代解读与启发" tabindex="-1">【解读层】现代解读与启发 <a class="header-anchor" href="#【解读层】现代解读与启发" aria-label="Permalink to &quot;【解读层】现代解读与启发&quot;">​</a></h2><p><strong>把关注点移回共同的事情。</strong> 团队讨论遇到争执时，可以先问怎样使问题解决，再讨论谁得到关注。清楚记录贡献、让适合的人承担工作，比把每一次发言都变成位置之争更有助于合作。</p><p><strong>区分不自我中心与忽视自己。</strong> 主动照顾整体时，也应说明自己的承受范围。能够持续的合作需要各方都得到适当支持；无私若被变成对某个人单方面付出的要求，就偏离了对共同关系的关照。</p><h2 id="【个人记录】我的笔记" tabindex="-1">【个人记录】我的笔记 <a class="header-anchor" href="#【个人记录】我的笔记" aria-label="Permalink to &quot;【个人记录】我的笔记&quot;">​</a></h2><p>留给自己的续读问题：我最近争取的是事情需要的位置，还是证明自己的位置？若暂时不争先，哪些责任与边界仍应说清？</p><h2 id="校读说明与参考来源" tabindex="-1">校读说明与参考来源 <a class="header-anchor" href="#校读说明与参考来源" aria-label="Permalink to &quot;校读说明与参考来源&quot;">​</a></h2><ul><li>「自生」依王弼与物争之注，理解为专为自身求生；「后」「外」作动词。</li><li>原页保留「邪」作句末反问语气词；HFL 电子录文此处作「耶」。</li><li>身先、身存是本章的义理表达，不宜直接转为退让必得回报或自我牺牲必有保障的承诺。</li></ul><p>参考：<a href="https://github.com/kanripo/KR5c0073/blob/b988441bd55861741c850e1dff4a2d4f895daf3d/KR5c0073_001.txt" target="_blank" rel="noreferrer">王弼《道德真经注》卷一 HFL 本电子录文，005a–005b</a>。</p>',15))])}}});export{_ as __pageData,k as default};
